import 'package:flutter/material.dart';
import '../../repositories/auth_repository.dart';
import '../../services/api/api_client.dart';
import '../routes/app_routes.dart';
import '../theme/app_colors.dart';
class RegisterScreen extends StatefulWidget{const RegisterScreen({super.key});@override State<RegisterScreen> createState()=>_RegisterScreenState();}
class _RegisterScreenState extends State<RegisterScreen>{final n=TextEditingController(),e=TextEditingController(),ph=TextEditingController(),pw=TextEditingController();bool loading=false;Future<void>_register()async{if(n.text.trim().isEmpty||e.text.trim().isEmpty||pw.text.length<6){_msg('Enter name, valid email and a password of at least 6 characters.');return;}setState(()=>loading=true);try{await RealAuthRepository(ApiClient()).register(name:n.text.trim(),email:e.text.trim(),phone:ph.text.trim(),password:pw.text,preferredLanguage:'en');if(mounted)Navigator.pushReplacementNamed(context,AppRoutes.home);}catch(x){_msg(x.toString());}if(mounted)setState(()=>loading=false);}void _msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));@override Widget build(BuildContext context)=>Scaffold(backgroundColor:AppColors.background,appBar:AppBar(title:const Text('Create Citizen Account')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Full name',prefixIcon:Icon(Icons.person_outline))),const SizedBox(height:12),TextField(controller:e,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',prefixIcon:Icon(Icons.email_outlined))),const SizedBox(height:12),TextField(controller:ph,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone number',prefixIcon:Icon(Icons.phone_outlined))),const SizedBox(height:12),TextField(controller:pw,obscureText:true,decoration:const InputDecoration(labelText:'Password',prefixIcon:Icon(Icons.lock_outline))),const SizedBox(height:22),SizedBox(height:50,child:ElevatedButton(onPressed:loading?null:_register,child:loading?const CircularProgressIndicator(color:Colors.white):const Text('CREATE ACCOUNT',style:TextStyle(fontWeight:FontWeight.w900))))]));@override void dispose(){n.dispose();e.dispose();ph.dispose();pw.dispose();super.dispose();}}
